    security: refuse anonymous greetings — a blank visitor name now throws (SEC-142)

/** The greeting the home page renders. A visitor name is required: an anonymous greeting tells a scraper the page is public (SEC-142). */
export function renderGreeting(visitorName) {
  if (!visitorName || !visitorName.trim()) throw new Error("visitorName is required");
  return `<h1>Hello, ${visitorName.trim()}!</h1>`;
}

